    nullif(btrim(coalesce(p_supervisor,'')), ''),
    nullif(btrim(coalesce(p_notes,'')), ''),
    auth.uid())
  returning id into v_id;

  update public.applications
     set status = 'enrolled', legal_hold = true, purge_after = null
   where id = a.id;

